name: PR Policy

permissions:
  pull-requests: read

on:
  pull_request_target:
    branches: ["main"]
    types:
      - opened
      - edited
      - synchronize
      - reopened
      - ready_for_review
      - converted_to_draft

jobs:
  pr-policy:
    name: pr-policy
    runs-on: ubuntu-latest
    steps:
      - name: Validate pull request contract
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          python3 - <<'PY'
          import json
          import os
          import re
          import sys
          from urllib import request

          with open(os.environ["GITHUB_EVENT_PATH"], "r", encoding="utf-8") as f:
              event = json.load(f)

          pr = event["pull_request"]
          title = pr.get("title") or ""
          body = pr.get("body") or ""
          author = (pr.get("user") or {}).get("login") or ""
          draft = bool(pr.get("draft"))

          bot_allowlist = {"dependabot[bot]", "github-actions[bot]"}
          is_bot = author in bot_allowlist
          release_sections = ("Release note", "Release category", "Breaking change")
          heading_re = re.compile(r"(?m)^##[ \t]+(.+?)[ \t]*$")
          if is_bot:
              token = os.environ.get("GH_TOKEN", "")
              repo = os.environ.get("GITHUB_REPOSITORY", "")
              number = pr.get("number")
              if not token or not repo or not isinstance(number, int):
                  print("::error::Bot PR metadata could not be checked.")
                  sys.exit(1)
              url = f"https://api.github.com/repos/{repo}/pulls/{number}"
              try:
                  with request.urlopen(request.Request(url, headers={
                      "Accept": "application/vnd.github+json",
                      "Authorization": f"Bearer {token}",
                      "X-GitHub-Api-Version": "2026-03-10",
                  }), timeout=10) as response:
                      current = json.load(response)
                  body = current.get("body") or ""
              except (OSError, ValueError, TypeError):
                  print("::error::Bot PR metadata could not be read.")
                  sys.exit(1)

          if draft and not is_bot:
              print("Draft PR: policy validation is deferred until the PR is ready for review.")
              sys.exit(0)

          errors = []

          title_pattern = re.compile(
              r"^(feat|fix|docs|test|refactor|perf|build|ci|chore)"
              r"(\([a-z0-9][a-z0-9._/-]*\))?!?: [A-Za-z0-9].+$"
          )
          if not title_pattern.fullmatch(title):
              errors.append(
                  "PR title must use Conventional Commits: "
                  "<type>(<scope>): <English summary>. "
                  "Allowed types: feat, fix, docs, test, refactor, perf, build, ci, chore."
              )
          if not title.isascii():
              errors.append("PR title must use English/ASCII characters.")

          required_sections = [
              "Summary",
              "Related issue",
              "Changes",
              "Verification",
              "Requirements impact",
              "Safety impact",
          ]

          matches = list(heading_re.finditer(body))
          sections = {}
          duplicates = set()

          for index, match in enumerate(matches):
              name = match.group(1).strip()
              start = match.end()
              end = matches[index + 1].start() if index + 1 < len(matches) else len(body)
              if name in sections:
                  duplicates.add(name)
              sections[name] = body[start:end]

          if not is_bot:
              for section in required_sections:
                  if section not in sections:
                      errors.append(f"Missing required section: ## {section}")
              for section in sorted(duplicates):
                  if section in required_sections:
                      errors.append(f"Required section appears more than once: ## {section}")

          comment_re = re.compile(r"<!--.*?-->", re.S)

          def cleaned(name):
              value = sections.get(name, "")
              return comment_re.sub("", value).strip()

          summary = cleaned("Summary")
          if not is_bot and "Summary" in sections and not summary:
              errors.append("Summary must not be empty.")

          related = cleaned("Related issue")
          if not is_bot and "Related issue" in sections:
              closes_issue = re.search(
                  r"(?i)\b(?:closes|fixes|resolves)\s+#\d+\b", related
              )
              explicit_na = re.search(r"(?im)^N/A:\s+\S.*$", related)
              if not (closes_issue or explicit_na):
                  errors.append(
                      "Related issue must contain 'Closes/Fixes/Resolves #<number>' "
                      "or 'N/A: <reason>'."
                  )

          changes = cleaned("Changes")
          meaningful_changes = re.sub(r"(?m)^[ \t]*[-*+][ \t]*$", "", changes).strip()
          if not is_bot and "Changes" in sections and not meaningful_changes:
              errors.append("Changes must contain at least one concrete change.")

          verification = cleaned("Verification")
          standard_checks = [
              "go test ./...",
              "go vet ./...",
              "go build ./cmd/commiter",
              "git diff --check",
          ]
          if not is_bot and "Verification" in sections:
              unchecked = []
              for check in standard_checks:
                  checked_re = re.compile(
                      rf"(?im)^[ \t]*-[ \t]+\[[xX]\][ \t]+\x60{re.escape(check)}\x60[ \t]*$"
                  )
                  if not checked_re.search(verification):
                      unchecked.append(check)

              skip_match = re.search(
                  r"(?is)Skipped / not applicable:\s*(.*)$", verification
              )
              skip_reason = skip_match.group(1).strip() if skip_match else ""

              if unchecked and (not skip_reason or skip_reason.lower() in {"none", "none."}):
                  errors.append(
                      "Verification must explain unchecked standard checks under "
                      "'Skipped / not applicable:'."
                  )

          requirements = cleaned("Requirements impact")
          if not is_bot and "Requirements impact" in sections:
              impact_options = [
                  "I believe this PR does not affect requirements.",
                  "I believe this PR may affect requirements.",
                  "I am unsure; maintainer review is required.",
              ]
              selected = 0
              for option in impact_options:
                  checked_re = re.compile(
                      rf"(?im)^[ \t]*-[ \t]+\[[xX]\][ \t]+{re.escape(option)}[ \t]*$"
                  )
                  if checked_re.search(requirements):
                      selected += 1

              if selected != 1:
                  errors.append("Select exactly one Requirements impact option.")

          safety = cleaned("Safety impact")
          if not is_bot and "Safety impact" in sections and not safety:
              errors.append(
                  "Safety impact must not be empty. Write 'None.' when not applicable."
              )

          for section in release_sections:
              if section not in sections:
                  errors.append(f"Missing required section: ## {section}")
          for section in sorted(duplicates):
              if section in release_sections:
                  errors.append(f"Required section appears more than once: ## {section}")

          release_categories = {
              "Added",
              "Changed",
              "Fixed",
              "Security",
              "Distribution",
              "Internal",
              "None",
          }
          breaking_options = {"Yes", "No"}
          checkbox_re = re.compile(r"(?m)^\s*-[ \t]+\[([ xX])\][ \t]+(.+?)[ \t]*$")

          def selected_release_option(section, allowed, label):
              selected = []
              for match in checkbox_re.finditer(sections.get(section, "")):
                  option = match.group(2).strip()
                  if option not in allowed:
                      errors.append(f"{label} contains an invalid option: {option}")
                  elif match.group(1).lower() == "x":
                      selected.append(option)
              if section in sections and len(selected) != 1:
                  errors.append(f"{label} must select exactly one option.")
              return selected[0] if len(selected) == 1 else None

          category = selected_release_option(
              "Release category", release_categories, "Release category"
          )
          selected_breaking = selected_release_option(
              "Breaking change", breaking_options, "Breaking change"
          )
          release_note = cleaned("Release note")
          if "Release note" in sections and not release_note:
              errors.append("English Release note must not be empty.")
          if (
              category in {"Added", "Changed", "Fixed", "Security", "Distribution"}
              and release_note.casefold() == "none"
          ):
              errors.append(
                  f"English Release note is required for category {category}."
              )
          if selected_breaking == "Yes" and release_note.casefold() == "none":
              errors.append("Breaking changes require an English Release note.")

          if errors:
              for error in errors:
                  print(f"::error::{error}")
              print(f"PR policy validation failed with {len(errors)} error(s).")
              sys.exit(1)

          print("PR policy validation passed.")
          PY

